<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Bar Counter Dashboard</title>
<style>
:root{--green:#2E8B57;--orange:#D96B27;--silver:#BFC5C7;--black:#17211B;--red:#C62828;--line:#dfe5e2;--soft:#f3f8f5}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Arial,sans-serif;background:#fff;color:var(--black)}button{font:inherit;cursor:pointer}.page{min-height:100vh;padding:8px 12px 14px;display:grid;grid-template-columns:274px minmax(0,1fr) 330px;grid-template-rows:58px 330px minmax(0,1fr);gap:12px}
.header{grid-column:1/-1;display:flex;align-items:center;padding:0 25px;border-radius:7px;background:var(--green);color:#fff}.header h1{margin:0;font-size:24px}.actions{margin-left:auto;display:flex;gap:14px}.actions button{height:40px;padding:0 25px;border:0;border-radius:6px;font-weight:700}.home{background:var(--silver);color:var(--black)}.refresh{background:var(--orange);color:#fff}.logout{background:#ed1725;color:#fff}
.card{border:1px solid var(--line);border-radius:7px;background:#fff;box-shadow:0 2px 8px #14283c09;overflow:hidden}.waiters{grid-column:1;grid-row:2/4;padding:18px 14px}.waiters h2,.panel h2{margin:0;font-size:16px;text-transform:uppercase}.waiter-list{height:calc(100% - 38px);overflow:auto;margin-top:18px;padding-right:2px}.waiter{display:grid;grid-template-columns:38px 1fr;gap:10px;align-items:center;width:100%;min-height:58px;margin-bottom:8px;padding:8px 10px;border:1px solid #bfdccc;border-radius:5px;background:var(--soft);color:var(--green);text-align:left}.initial{display:grid;place-items:center;width:32px;height:32px;border:2px solid var(--green);border-radius:50%;background:#fff;font-weight:800}.waiter strong,.waiter small{display:block}.waiter small{margin-top:4px;font-size:12px}.waiter small b{float:right}.add{display:flex;justify-content:center;align-items:center;min-height:58px;border:1px dashed #b9c9c0;border-radius:5px;color:var(--green);font-weight:700}
.overview{grid-column:2;grid-row:2;display:grid;grid-template-columns:minmax(0,1.65fr) minmax(250px,.9fr);gap:12px}.hero{position:relative;padding:20px 24px;border-radius:7px;background:var(--green);color:#fff}.hero small{font-size:14px;font-weight:700}.hero strong{display:block;margin-top:4px;font-size:52px}.balance{position:absolute;top:111px;left:24px;padding:9px 14px;border:0;border-radius:6px;background:var(--orange);color:#fff;font-weight:800}.change{position:absolute;top:50px;right:24px;text-align:center}.change b{display:block;padding:8px 13px;border-radius:6px;background:#fff;color:var(--green)}.change small{display:block;margin-top:7px}.chart{position:absolute;left:24px;right:24px;bottom:17px;height:150px}.chart svg{width:100%;height:100%}.gridline{stroke:#ffffff55}.line{fill:none;stroke:#fff;stroke-width:2.5}.point{fill:#fff}.labels{fill:#fff;font-size:10px}.breakdown{padding:20px;background:#eef1f0}.breakdown h2{margin:0;font-size:16px;text-transform:uppercase}.donut{width:162px;height:162px;margin:40px auto 15px;border-radius:50%;background:conic-gradient(var(--green) 0 32.6%,#2678c9 32.6% 61.2%,#ffb21a 61.2% 100%);position:relative}.donut:after{content:"";position:absolute;inset:34px;border-radius:50%;background:#eef1f0}.donut span{position:absolute;inset:0;z-index:1;display:grid;place-content:center;text-align:center;font-weight:800;font-size:20px}.legend{display:grid;gap:8px}.legend div{font-size:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:7px}
.snapshot{grid-column:2;grid-row:3;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:190px minmax(0,1fr);gap:12px}.snapshot-box{grid-column:1/-1;padding:14px 20px;background:var(--silver)}.snapshot-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 35px}.snap{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #fff;font-size:16px}.snap span{flex:1}.snap b{font-size:18px}.green{color:var(--green)}.bad{color:var(--red)}
.receipts{padding:0 18px}.receipts h2{margin:14px 0 8px;font-size:16px;text-transform:uppercase}.receipt-scroll{height:calc(100% - 45px);overflow:auto}.receipts table{width:100%;border-collapse:collapse;font-size:11px}.receipts th{text-align:left;color:#64736b;padding:7px 4px;border-bottom:1px solid var(--line)}.receipts td{padding:7px 4px;border-bottom:1px solid var(--line);white-space:nowrap}.receipts th:last-child,.receipts td:last-child{text-align:right}.reprint{padding:5px 9px;border:1px solid var(--green);border-radius:5px;background:#fff;color:var(--green);font-size:10px;font-weight:700}
.totals{padding:14px 20px;background:var(--silver)}.totals h2{margin:0 0 6px;font-size:16px;text-transform:uppercase}.total-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #fff;font-size:16px}.total-row i{font-style:normal;font-size:25px;color:var(--green)}.total-row span{flex:1}.total-row b{font-size:20px}.split{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:13px 0;border-bottom:1px solid #fff}.split div{display:flex;gap:8px;align-items:center}.split b{font-size:18px}.performance{position:absolute;top:493px;right:12px;width:330px;height:478px;padding:0 14px}.performance .scroll{height:calc(100% - 45px);overflow:auto}.perf{display:grid;grid-template-columns:25px 30px 1fr auto;gap:8px;align-items:center;padding:13px 0;border-bottom:1px solid var(--line);font-size:12px}.perf .initial{width:29px;height:29px;background:var(--green);color:#fff;border:0}.alerts{position:absolute;top:80px;right:12px;width:330px;height:392px;padding:0 10px;background:#fff5f5;border:1px solid #ff8f8f}.alerts .scroll{height:calc(100% - 45px);overflow:auto}.alert{display:flex;align-items:center;justify-content:space-between;min-height:43px;margin:6px 0;padding:0 10px;border:1px solid #ff8f8f;border-radius:6px;color:var(--red);font-size:12px}.alert b{display:grid;place-items:center;min-width:32px;height:30px;border-radius:6px;background:var(--red);color:#fff;font-size:15px}
@media(max-width:1000px){.page{display:block;padding:10px}.header,.waiters,.overview,.snapshot,.performance,.alerts{position:static;width:auto;margin-bottom:10px}.header{min-height:58px}.waiters{min-height:500px}.overview{display:grid;grid-template-columns:1fr 1fr}.snapshot{display:grid}.performance,.alerts{min-height:360px}.receipt-scroll{height:auto;max-height:420px}}
@media(max-width:650px){.header{padding:0 12px}.header h1{font-size:18px}.actions{gap:5px}.actions button{padding:0 10px;font-size:11px}.overview,.snapshot{display:block}.overview>*{margin-bottom:10px}.hero{min-height:310px}.hero strong{font-size:40px}.snapshot-box,.receipts,.totals{margin-bottom:10px}.snapshot-box{min-height:220px}.performance,.alerts{min-height:300px}.receipts table{min-width:620px}.receipt-scroll{overflow:auto}}
</style>
</head>
<body>
<main class="page">
<header class="header"><h1>Bar Counter Dashboard</h1><div class="actions"><button class="home">⌂ &nbsp; Home</button><button class="refresh">⟳ &nbsp; Refresh</button><button class="logout">⇥ &nbsp; Logout</button></div></header>
<section class="card waiters"><h2>Waiters Posted to<br>This Counter</h2><div class="waiter-list">
<button class="waiter"><span class="initial">K</span><span><strong>KTOUCH_ADMIN</strong><small>23 orders <b>KES 75,860</b></small></span></button>
<button class="waiter"><span class="initial">Y</span><span><strong>YANGA</strong><small>1 order <b>KES 13,450</b></small></span></button>
<button class="waiter"><span class="initial">S</span><span><strong>SAMMY</strong><small>0 orders <b>KES 0</b></small></span></button>
<button class="waiter"><span class="initial">M</span><span><strong>MARY</strong><small>0 orders <b>KES 0</b></small></span></button>
<button class="waiter"><span class="initial">J</span><span><strong>JOHN</strong><small>0 orders <b>KES 0</b></small></span></button><div class="add">♙ &nbsp; Add Waiter</div></div></section>
<section class="overview"><div class="hero"><small>COUNTER SALES — CURRENT SHIFT</small><strong>KES 89,310</strong><button class="balance">! &nbsp; SALES &amp; ITEMS NOT BALANCED</button><div class="change"><b>↑ 12.4%</b><small>vs previous shift</small></div><div class="chart"><svg viewBox="0 0 640 150" preserveAspectRatio="none"><g class="gridline"><line x1="38" y1="18" x2="625" y2="18"/><line x1="38" y1="58" x2="625" y2="58"/><line x1="38" y1="98" x2="625" y2="98"/><line x1="38" y1="138" x2="625" y2="138"/></g><path class="line" d="M42 111 L91 111 L140 75 L189 60 L238 108 L287 103 L336 88 L385 108 L434 20 L483 82 L532 111 L581 111 L620 63"/><g class="point"><circle cx="42" cy="111" r="4"/><circle cx="140" cy="75" r="4"/><circle cx="189" cy="60" r="4"/><circle cx="434" cy="20" r="4"/><circle cx="620" cy="63" r="4"/></g><g class="labels"><text x="35" y="149">10 AM</text><text x="130" y="149">12 PM</text><text x="228" y="149">2 PM</text><text x="326" y="149">4 PM</text><text x="424" y="149">6 PM</text><text x="522" y="149">8 PM</text><text x="600" y="149">10 PM</text></g></svg></div></div><div class="card breakdown"><h2>Sales Breakdown</h2><div class="donut"><span>KES<br>89.3K</span></div><div class="legend"><div><i class="dot" style="background:#2E8B57"></i>Bar &nbsp; KES 89,310</div><div><i class="dot" style="background:#2678c9"></i>Counter B &nbsp; KES 0</div></div></div></section>
<section class="snapshot"><div class="card snapshot-box"><h2>Counter Snapshot</h2><div class="snapshot-grid"><div class="snap"><span>◷ &nbsp; Opening Time</span><b>12:58 PM</b></div><div class="snap"><span>▣ &nbsp; Orders</span><b>24</b></div><div class="snap"><span>◉ &nbsp; Shift Status</span><b class="green">Open</b></div><div class="snap"><span>▣ &nbsp; Items Sold</span><b>134</b></div><div class="snap"><span>↻ &nbsp; Returns</span><b>1</b></div><div class="snap"><span>✓ &nbsp; Reconciliation</span><b class="bad">Balancing Pending</b></div></div></div><section class="card receipts"><h2>Last 10 Receipts</h2><div class="receipt-scroll"><table><thead><tr><th>Receipt</th><th>Waiter</th><th>Time</th><th>Amount</th><th>Action</th></tr></thead><tbody>
<tr><td><b>#R-114</b></td><td>KTOUCH_ADMIN</td><td>19:36:29</td><td>KES 1,201</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-113</b></td><td>KTOUCH_ADMIN</td><td>19:22:58</td><td>KES 1,881</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-112</b></td><td>KTOUCH_ADMIN</td><td>19:07:11</td><td>KES 1,200</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-111</b></td><td>KTOUCH_ADMIN</td><td>18:58:32</td><td>KES 5,646</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-110</b></td><td>KTOUCH_ADMIN</td><td>18:08:04</td><td>KES 6,167</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-109</b></td><td>KTOUCH_ADMIN</td><td>17:57:54</td><td>KES 1,600</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-108</b></td><td>KTOUCH_ADMIN</td><td>16:22:28</td><td>KES 5,200</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-107</b></td><td>KTOUCH_ADMIN</td><td>15:48:03</td><td>KES 2,450</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-106</b></td><td>KTOUCH_ADMIN</td><td>14:27:19</td><td>KES 3,750</td><td><button class="reprint">▣ Reprint</button></td></tr><tr><td><b>#R-105</b></td><td>KTOUCH_ADMIN</td><td>13:35:44</td><td>KES 4,900</td><td><button class="reprint">▣ Reprint</button></td></tr></tbody></table></div></section><section class="card totals"><h2>Counter Totals</h2><div class="total-row"><i>▣</i><span>Total Orders</span><b>24</b></div><div class="total-row"><i>▤</i><span>Items Sold</span><b>134</b></div><div class="total-row"><i>↻</i><span>Returns</span><b>1</b></div><div class="split"><div><i class="green">✓</i><span>Approved<br><b>1</b></span></div><div><i class="bad">×</i><span>Rejected<br><b>0</b></span></div></div><div class="split"><div><i>↔</i><span>Transfers In<br><b>0</b></span></div><div><i>↔</i><span>Transfers Out<br><b>0</b></span></div></div><div class="total-row"><i class="bad">◷</i><span>Counter Status</span><b class="bad">Balancing Pending</b></div></section></section>
<section class="card alerts"><div class="panel"><h2>Alerts</h2><div class="scroll"><div class="alert"><span>⚠ Below Reorder</span><b>6</b></div><div class="alert"><span>⊘ Stock Out</span><b>3</b></div><div class="alert"><span>↻ Returns</span><b>1</b></div><div class="alert"><span>▣ Requests Pending Receiving</span><b>4</b></div><div class="alert"><span>→ Transfers Sent</span><b>2</b></div><div class="alert"><span>↔ Transfer Requests</span><b>2</b></div><div class="alert"><span>! Voids</span><b>1</b></div></div></div></section>
<section class="card performance"><div class="panel"><h2>Waiter Performance</h2><div class="scroll"><div class="perf"><span>1</span><span class="initial">K</span><strong>KTOUCH_ADMIN</strong><b>KES 75,860</b></div><div class="perf"><span>2</span><span class="initial">Y</span><strong>YANGA</strong><b>KES 13,450</b></div><div class="perf"><span>3</span><span class="initial">S</span><strong>SAMMY</strong><b>KES 0</b></div><div class="perf"><span>4</span><span class="initial">M</span><strong>MARY</strong><b>KES 0</b></div><div class="perf"><span>5</span><span class="initial">J</span><strong>JOHN</strong><b>KES 0</b></div></div></div></section>
</main></body></html>
